// ---- helpers ------------------------------------------------------------------------------

fn js(e: &Error) -> &JsError {
    match e {
        Error::Js(j) => j,
        other => panic!("expected Error::Js, got {other:?}"),
    }
}

/// (name, message, code) of an error.
fn shape(e: &Error) -> (String, String, Option<String>) {
    (e.name().to_string(), e.message(), e.code().map(str::to_string))
}

/// The `cause` of `TypeError: fetch failed` / `TypeError: terminated`.
fn cause(e: &Error) -> &Error {
    js(e).cause.as_deref().unwrap_or_else(|| panic!("no cause on {e:?}"))
}

fn fetch_failed(e: &Error) -> (String, String, Option<String>) {
    assert_eq!(
        shape(e),
        ("TypeError".to_string(), "fetch failed".to_string(), None),
        "{e:?}"
    );
    shape(cause(e))
}

fn s(x: &str) -> String {
    x.to_string()
}

#[derive(Clone, Debug)]
struct Captured {
    method: String,
    path: String,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

impl Captured {
    fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(k, _)| k.eq_ignore_ascii_case(name))
            .map(|(_, v)| v.as_str())
    }
}

enum Reply {
    /// Raw bytes, then close.
    Raw(Vec<u8>),
    /// Raw pieces written with a pause before each, then close.
    Paced(Vec<(u64, Vec<u8>)>),
}

fn reply(status: &str, headers: &[(&str, &str)], body: &[u8]) -> Reply {
    let mut out = format!("HTTP/1.1 {status}\r\n");
    for (k, v) in headers {
        out.push_str(&format!("{k}: {v}\r\n"));
    }
    out.push_str(&format!("content-length: {}\r\nconnection: close\r\n\r\n", body.len()));
    let mut bytes = out.into_bytes();
    bytes.extend_from_slice(body);
    Reply::Raw(bytes)
}

struct Server {
    addr: SocketAddr,
    seen: Arc<Mutex<Vec<Captured>>>,
}

impl Server {
    fn url(&self, path: &str) -> String {
        format!("http://{}{path}", self.addr)
    }

    fn requests(&self) -> Vec<Captured> {
        self.seen.lock().unwrap().clone()
    }
}

async fn read_request(sock: &mut TcpStream) -> Option<Captured> {
    let mut buf = Vec::new();
    let mut tmp = [0u8; 4096];
    let head_end = loop {
        if let Some(i) = buf.windows(4).position(|w| w == b"\r\n\r\n") {
            break i;
        }
        let n = sock.read(&mut tmp).await.ok()?;
        if n == 0 {
            return None;
        }
        buf.extend_from_slice(&tmp[..n]);
    };
    let head = String::from_utf8_lossy(&buf[..head_end]).into_owned();
    let mut lines = head.split("\r\n");
    let mut first = lines.next()?.split(' ');
    let method = first.next()?.to_string();
    let path = first.next()?.to_string();
    let headers: Vec<(String, String)> = lines
        .filter_map(|l| l.split_once(':'))
        .map(|(k, v)| (k.to_string(), v.trim().to_string()))
        .collect();
    let len: usize = headers
        .iter()
        .find(|(k, _)| k.eq_ignore_ascii_case("content-length"))
        .and_then(|(_, v)| v.parse().ok())
        .unwrap_or(0);
    let mut body = buf[head_end + 4..].to_vec();
    while body.len() < len {
        let n = sock.read(&mut tmp).await.ok()?;
        if n == 0 {
            break;
        }
        body.extend_from_slice(&tmp[..n]);
    }
    Some(Captured {
        method,
        path,
        headers,
        body,
    })
}

async fn serve(handler: impl Fn(&Captured, SocketAddr) -> Reply + Send + Sync + 'static) -> Server {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    let seen = Arc::new(Mutex::new(Vec::new()));
    let handler = Arc::new(handler);
    let log = seen.clone();
    tokio::spawn(async move {
        loop {
            let Ok((mut sock, _)) = listener.accept().await else {
                return;
            };
            let handler = handler.clone();
            let log = log.clone();
            tokio::spawn(async move {
                let Some(req) = read_request(&mut sock).await else {
                    return;
                };
                log.lock().unwrap().push(req.clone());
                match handler(&req, addr) {
                    Reply::Raw(bytes) => {
                        let _ = sock.write_all(&bytes).await;
                    }
                    Reply::Paced(parts) => {
                        for (pause, bytes) in parts {
                            tokio::time::sleep(Duration::from_millis(pause)).await;
                            if sock.write_all(&bytes).await.is_err() {
                                return;
                            }
                        }
                    }
                }
                let _ = sock.shutdown().await;
            });
        }
    });
    Server { addr, seen }
}

/// Echoes the request as JSON and serves the redirect fixtures of the Node probe.
async fn echo_server() -> Server {
    serve(|req, addr| match req.path.as_str() {
        "/r301" => reply("301 Moved Permanently", &[("location", "/echo")], b"moved"),
        "/r302" => reply("302 Found", &[("location", "/echo")], b""),
        "/r303" => reply("303 See Other", &[("location", "/echo")], b""),
        "/r307" => reply("307 Temporary Redirect", &[("location", "/echo")], b""),
        "/loop" => reply("302 Found", &[("location", "/loop")], b""),
        "/noloc" => reply("302 Found", &[], b"x"),
        "/badloc" => reply("302 Found", &[("location", "ftp://x/")], b"x"),
        "/frag" => reply("302 Found", &[("location", "/echo")], b""),
        "/abs" => reply("302 Found", &[("location", &format!("http://{addr}/echo?abs=1"))], b""),
        "/204" => reply("204 No Content", &[], b""),
        "/close" => Reply::Paced(vec![
            (
                0,
                b"HTTP/1.1 200 OK\r\ncontent-length: 100\r\nconnection: close\r\n\r\npartial".to_vec(),
            ),
            (20, Vec::new()),
        ]),
        "/gzip" => reply(
            "200 OK",
            &[("content-encoding", "gzip"), ("content-type", "text/plain")],
            GZIP_HELLO,
        ),
        "/br" => reply("200 OK", &[("content-encoding", "br")], BROTLI_HELLO),
        "/bom" => reply("200 OK", &[], b"\xEF\xBB\xBFhi \xFF!"),
        "/json" => reply(
            "200 OK",
            &[("content-type", "application/json")],
            br#"{"b":1,"a":[true,null]}"#,
        ),
        "/badjson" => reply("200 OK", &[], br#"{"a":"#),
        "/headers" => reply(
            "200 OK",
            &[
                ("content-type", "application/json"),
                ("x-dup", "1"),
                ("x-dup", "2"),
                ("set-cookie", "a=1"),
                ("set-cookie", "b=2"),
                ("x-latin", "caf\u{e9}"),
            ],
            b"{}",
        ),
        "/slow-headers" => Reply::Paced(vec![(
            2000,
            b"HTTP/1.1 200 OK\r\ncontent-length: 2\r\nconnection: close\r\n\r\nok".to_vec(),
        )]),
        "/slow-body" => Reply::Paced(vec![
            (
                0,
                b"HTTP/1.1 200 OK\r\ncontent-length: 10\r\nconnection: close\r\n\r\nfirst".to_vec(),
            ),
            (2000, b"second".to_vec()),
        ]),
        "/sse" => Reply::Paced(vec![
            (
                0,
                b"HTTP/1.1 200 OK\r\ncontent-type: text/event-stream\r\nconnection: close\r\n\r\n".to_vec(),
            ),
            (5, b"\xEF\xBB\xBFevent: start\ndata: {\"n\":1}\n".to_vec()),
            (5, b"\n: keep-alive\n\ndata: caf\xC3".to_vec()),
            (
                5,
                b"\xA9\r\ndata: two\r\n\r\nid: 3\nretry: 50\ndata: end\n\ndata: dangling".to_vec(),
            ),
        ]),
        _ => {
            let body = serde_json::json!({
                "method": req.method,
                "path": req.path,
                "content_type": req.header("content-type"),
                "authorization": req.header("authorization"),
                "body": String::from_utf8_lossy(&req.body),
            });
            reply(
                "200 OK",
                &[("content-type", "application/json")],
                body.to_string().as_bytes(),
            )
        }
    })
    .await
}

fn sorted_headers(req: &Captured) -> Vec<(String, String)> {
    let mut h: Vec<(String, String)> = req
        .headers
        .iter()
        .filter(|(k, _)| !k.eq_ignore_ascii_case("host"))
        .map(|(k, v)| (k.to_ascii_lowercase(), v.clone()))
        .collect();
    h.sort();
    h
}

fn pairs(list: &[(&str, &str)]) -> Vec<(String, String)> {
    let mut v: Vec<(String, String)> = list.iter().map(|(k, v)| (s(k), s(v))).collect();
    v.sort();
    v
}

// ---- Headers ------------------------------------------------------------------------------

#[test]
fn headers_validation_matches_undici() {
    let err = |pairs: &[(&str, &str)]| shape(&Headers::try_from_pairs(pairs.iter().copied()).unwrap_err());
    assert_eq!(
        err(&[("bad name", "x")]),
        (
            s("TypeError"),
            s("Headers.append: \"bad name\" is an invalid header name."),
            None
        )
    );
    assert_eq!(
        err(&[("", "x")]),
        (
            s("TypeError"),
            s("Headers.append: \"\" is an invalid header name."),
            None
        )
    );
    assert_eq!(
        err(&[("a", "x\ny")]),
        (
            s("TypeError"),
            s("Headers.append: \"x\ny\" is an invalid header value."),
            None
        )
    );
    assert_eq!(
        err(&[("a", "x\0y")]),
        (
            s("TypeError"),
            s("Headers.append: \"x\0y\" is an invalid header value."),
            None
        )
    );
    assert_eq!(
        err(&[("a", "x€y")]),
        (
            s("TypeError"),
            s(
                "Cannot convert argument to a ByteString because the character at index 1 has a value of 8364 which is greater than 255."
            ),
            None
        )
    );
    let mut h = Headers::new();
    assert_eq!(
        shape(&h.try_set("a", "😀").unwrap_err()).1,
        "Cannot convert argument to a ByteString because the character at index 0 has a value of 55357 which is greater than 255."
    );
    assert_eq!(
        shape(&h.try_set("a b", "x").unwrap_err()).1,
        "Headers.set: \"a b\" is an invalid header name."
    );
    let ok = Headers::try_from_pairs([("a", "xéy"), ("b", " \t x y \r\n")]).unwrap();
    assert_eq!(ok.get("a").as_deref(), Some("xéy"));
    assert_eq!(ok.get("b").as_deref(), Some("x y"));
    assert_eq!(ok.get("bad name"), None);
}

#[test]
fn headers_order_and_combining_match_whatwg() {
    let mut h = Headers::new();
    h.append("B", "1");
    h.append("a", "2");
    h.append("b", "3");
    h.set("A", "4");
    h.append("Set-Cookie", "x");
    h.append("set-cookie", "y");
    // Node: [["a","4"],["b","1, 3"],["set-cookie","x"],["set-cookie","y"]], "1, 3", ["x","y"], true
    assert_eq!(
        h.entries(),
        vec![
            (s("a"), s("4")),
            (s("b"), s("1, 3")),
            (s("set-cookie"), s("x")),
            (s("set-cookie"), s("y"))
        ]
    );
    assert_eq!(h.get("B").as_deref(), Some("1, 3"));
    assert_eq!(h.get_set_cookie(), vec![s("x"), s("y")]);
    assert!(h.has("SET-COOKIE"));
    assert_eq!(h.get("set-cookie").as_deref(), Some("x, y"));
    assert_eq!(h.keys(), vec![s("a"), s("b"), s("set-cookie"), s("set-cookie")]);
    // Names keep the casing of their first occurrence in the raw list.
    assert_eq!(h.raw()[0], (s("B"), s("1")));
    assert_eq!(h.raw()[1], (s("a"), s("4")));
    assert_eq!(h.raw()[2], (s("B"), s("3")));
    h.set("b", "5");
    assert_eq!(h.raw().iter().filter(|(k, _)| k.eq_ignore_ascii_case("b")).count(), 1);
    assert_eq!(h.raw()[0], (s("B"), s("5")));
    h.delete("SET-cookie");
    assert_eq!(h.entries(), vec![(s("a"), s("4")), (s("b"), s("5"))]);
    assert_eq!(
        Headers::from_pairs([("x", "1")]),
        [("X", "1")].into_iter().collect::<Headers>().with_lower_names()
    );
}

trait LowerNames {
    fn with_lower_names(self) -> Headers;
}

impl LowerNames for Headers {
    fn with_lower_names(self) -> Headers {
        Headers::from_pairs(self.raw().iter().map(|(k, v)| (k.to_ascii_lowercase(), v.clone())))
    }
}

// ---- SSE ----------------------------------------------------------------------------------

fn parse_all(parser: &mut SseParser, body: &[u8], chunk: usize) -> Vec<SseEvent> {
    body.chunks(chunk.max(1)).flat_map(|c| parser.feed(c)).collect()
}

#[test]
fn sse_parser_matches_undici_event_source() {
    for case in SSE {
        let expected: Vec<(String, String, String)> = case.events.iter().map(|(t, d, i)| (s(t), s(d), s(i))).collect();
        for chunk in [usize::MAX, 1, 2, 3, 7] {
            let got: Vec<(String, String, String)> = parse_all(&mut SseParser::new(), case.body, chunk)
                .into_iter()
                .map(|e| (e.event, e.data, e.id.unwrap_or_default()))
                .collect();
            assert_eq!(
                got,
                expected,
                "body {:?} in chunks of {chunk}",
                String::from_utf8_lossy(case.body)
            );
        }
    }
}

#[test]
fn sse_parser_reports_retry_and_persistent_id() {
    let events =
        SseParser::new().feed_str("retry: 1500\n\nid: 4\ndata: a\n\ndata: b\nretry: x\n\nretry: 20\ndata: c\n\n");
    assert_eq!(
        events,
        vec![
            SseEvent {
                event: s("message"),
                data: s("a"),
                id: Some(s("4")),
                retry: Some(1500)
            },
            SseEvent {
                event: s("message"),
                data: s("b"),
                id: Some(s("4")),
                retry: None
            },
            SseEvent {
                event: s("message"),
                data: s("c"),
                id: Some(s("4")),
                retry: Some(20)
            },
        ]
    );
    let mut p = SseParser::new();
    p.feed_str("id: 9\n");
    assert_eq!(p.last_event_id(), "9");
}

// ---- mock_fetch / deny_network -------------------------------------------------------------

#[tokio::test]
async fn mock_fetch_sees_the_request_as_built_and_restores_on_drop() {
    let seen = Arc::new(Mutex::new(Vec::new()));
    let log = seen.clone();
    let guard = testing::mock_fetch(move |req: Request| {
        log.lock().unwrap().push((
            req.method.clone(),
            req.url.clone(),
            req.headers.entries(),
            req.body_json(),
        ));
        Box::pin(async move {
            Ok(testing::response(
                201,
                &[("content-type", "application/json")],
                r#"{"ok":true}"#,
            ))
        })
    });
    let req = Request::post("https://api.example.com/v1/messages")
        .header("x-api-key", "k")
        .header("content-type", "application/json")
        .body(r#"{"model":"m","stream":true}"#);
    let res = fetch::fetch(req).await.unwrap();
    assert_eq!(res.status(), 201);
    assert!(res.ok());
    assert_eq!(res.status_text(), "");
    assert_eq!(res.url(), "");
    assert_eq!(res.json().await.unwrap(), serde_json::json!({"ok": true}));
    assert_eq!(
        seen.lock().unwrap().clone(),
        vec![(
            s("POST"),
            s("https://api.example.com/v1/messages"),
            vec![(s("content-type"), s("application/json")), (s("x-api-key"), s("k"))],
            Some(serde_json::json!({"model": "m", "stream": true})),
        )]
    );
    {
        let _inner = testing::deny_network();
        let err = fetch::fetch(Request::get("https://example.com/x")).await.unwrap_err();
        let (name, message, _) = fetch_failed(&err);
        assert_eq!(name, "Error");
        assert!(
            message.contains("deny_network") && message.contains("GET https://example.com/x"),
            "{message}"
        );
    }
    // The outer mock is back after the inner guard dropped.
    assert_eq!(fetch::fetch(Request::get("https://x/")).await.unwrap().status(), 201);
    drop(guard);
    assert_eq!(seen.lock().unwrap().len(), 2);
}

#[tokio::test]
async fn mock_fetch_is_thread_local() {
    let _guard = testing::mock_fetch(|_| Box::pin(async { Ok(testing::response(299, &[], "mocked")) }));
    let other = std::thread::spawn(|| {
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        rt.block_on(async {
            let _deny = testing::deny_network();
            fetch::fetch(Request::get("http://127.0.0.1:9/"))
                .await
                .map(|r| r.status())
                .map_err(|e| e.to_string())
        })
    })
    .join()
    .unwrap();
    assert_eq!(other, Err(s("fetch failed")));
    assert_eq!(
        fetch::fetch(Request::get("http://x/"))
            .await
            .unwrap()
            .text()
            .await
            .unwrap(),
        "mocked"
    );
}

#[tokio::test]
async fn constructed_responses_follow_body_rules() {
    let res = testing::response(200, &[("a", "1")], "hello");
    assert!(res.has_body());
    assert!(!res.body_used());
    assert_eq!(res.text().await.unwrap(), "hello");
    assert!(res.body_used());
    assert_eq!(
        shape(&res.text().await.unwrap_err()),
        (s("TypeError"), s("Body is unusable: Body has already been read"), None)
    );
    assert_eq!(
        shape(&res.body_stream().unwrap_err()),
        (
            s("TypeError"),
            s("Invalid state: ReadableStream is locked"),
            Some(s("ERR_INVALID_STATE"))
        )
    );

    let locked = testing::response(200, &[], "x");
    let _stream = locked.body_stream().unwrap();
    assert_eq!(
        shape(&locked.bytes().await.unwrap_err()).1,
        "Body is unusable: Body has already been read"
    );

    let null = Response::null_body(204, Headers::new());
    assert!(!null.has_body());
    assert_eq!(null.text().await.unwrap(), "");
    assert_eq!(null.text().await.unwrap(), "");
    assert!(!null.body_used());

    let chunked = testing::chunked_response(200, &[], vec!["a", "b", "c"]);
    let chunks: Vec<Bytes> = chunked.body_stream().unwrap().map(|c| c.unwrap()).collect().await;
    assert_eq!(chunks, vec![Bytes::from("a"), Bytes::from("b"), Bytes::from("c")]);

    let cancelled = testing::response(200, &[], "x");
    cancelled.cancel_body();
    assert!(cancelled.body_used());

    assert_eq!(
        shape(&testing::response(200, &[], "").json().await.unwrap_err()),
        (s("SyntaxError"), s("Unexpected end of JSON input"), None)
    );
    assert_eq!(
        shape(&testing::response(200, &[], r#"{"a":"#).json().await.unwrap_err()).1,
        "Unexpected end of JSON input"
    );
    // Node 24 `await new Response(body).json()` messages.
    for (body, message) in [
        (
            "{bad",
            "Expected property name or '}' in JSON at position 1 (line 1 column 2)",
        ),
        ("hello", "Unexpected token 'h', \"hello\" is not valid JSON"),
        ("[1,]", "Unexpected token ']', \"[1,]\" is not valid JSON"),
    ] {
        let err = testing::response(200, &[], body).json().await.unwrap_err();
        assert_eq!(shape(&err), (s("SyntaxError"), s(message), None), "{body}");
    }
    let bom = testing::response(200, &[], &b"\xEF\xBB\xBF{\"a\":1}"[..]);
    assert_eq!(bom.json().await.unwrap(), serde_json::json!({"a": 1}));

    let sse = testing::chunked_response(
        200,
        &[("content-type", "text/event-stream")],
        vec!["data: 1\n", "\ndata: 2\n\n"],
    );
    let events: Vec<String> = sse.sse().unwrap().map(|e| e.unwrap().data).collect().await;
    assert_eq!(events, vec![s("1"), s("2")]);
}

