#[tokio::test]
async fn request_validation_matches_undici() {
    let check = |req: Request| async move { shape(&fetch::fetch(req).await.unwrap_err()) };
    let url_err = fetch::fetch(Request::get("not a url")).await.unwrap_err();
    assert_eq!(
        shape(&url_err),
        (s("TypeError"), s("Failed to parse URL from not a url"), None)
    );
    assert_eq!(
        shape(cause(&url_err)),
        (s("TypeError"), s("Invalid URL"), Some(s("ERR_INVALID_URL")))
    );
    assert_eq!(
        check(Request::get("http://user:pw@127.0.0.1:1/")).await,
        (
            s("TypeError"),
            s("Request cannot be constructed from a URL that includes credentials: http://user:pw@127.0.0.1:1/"),
            None
        )
    );
    assert_eq!(
        check(Request::get("http://127.0.0.1:1/").body("x")).await,
        (
            s("TypeError"),
            s("Request with GET/HEAD method cannot have body."),
            None
        )
    );
    assert_eq!(
        check(Request::new("head", "http://127.0.0.1:1/").body("x")).await,
        (
            s("TypeError"),
            s("Request with GET/HEAD method cannot have body."),
            None
        )
    );
    assert_eq!(
        check(Request::new("CONNECT", "http://127.0.0.1:1/")).await,
        (s("TypeError"), s("'CONNECT' HTTP method is unsupported."), None)
    );
    assert_eq!(
        check(Request::new("trace", "http://127.0.0.1:1/")).await,
        (s("TypeError"), s("'trace' HTTP method is unsupported."), None)
    );
    assert_eq!(
        check(Request::new("BAD METHOD", "http://127.0.0.1:1/")).await,
        (s("TypeError"), s("'BAD METHOD' is not a valid HTTP method."), None)
    );
    assert_eq!(
        check(Request::get("http://127.0.0.1:1/").header("bad name", "x")).await,
        (
            s("TypeError"),
            s("Headers.append: \"bad name\" is an invalid header name."),
            None
        )
    );
    let ftp = fetch::fetch(Request::get("ftp://127.0.0.1/x")).await.unwrap_err();
    assert_eq!(fetch_failed(&ftp), (s("Error"), s("unknown scheme"), None));
    let file = fetch::fetch(Request::get("file:///etc/hosts")).await.unwrap_err();
    assert_eq!(fetch_failed(&file).1, "not implemented... yet...");
    let about = fetch::fetch(Request::get("about:blank")).await.unwrap_err();
    assert_eq!(fetch_failed(&about).1, "about scheme is not supported");
    for url in ["blob:http://x/0", "blob:http://x/0?"] {
        let blob = fetch::fetch(Request::get(url)).await.unwrap_err();
        assert_eq!(fetch_failed(&blob).1, "invalid method", "{url}");
    }
    let blob = fetch::fetch(Request::get("blob:http://x/0?q")).await.unwrap_err();
    assert_eq!(fetch_failed(&blob).1, "NetworkError when attempting to fetch resource.");
    let bad_port = fetch::fetch(Request::get("http://127.0.0.1:1/")).await.unwrap_err();
    assert_eq!(fetch_failed(&bad_port), (s("Error"), s("bad port"), None));
    let bad_port = fetch::fetch(Request::get("http://127.0.0.1:6667/")).await.unwrap_err();
    assert_eq!(fetch_failed(&bad_port).1, "bad port");
}

