#[tokio::test]
async fn sends_undici_default_headers() {
    let server = echo_server().await;
    fetch::fetch(Request::get(server.url("/p?q=1")))
        .await
        .unwrap()
        .text()
        .await
        .unwrap();
    fetch::fetch(
        Request::post(server.url("/p"))
            .header("X-Custom", "A")
            .header("b-h", "1")
            .body("hello"),
    )
    .await
    .unwrap()
    .text()
    .await
    .unwrap();
    fetch::fetch(Request::post(server.url("/p")).body(vec![1u8, 2]))
        .await
        .unwrap()
        .text()
        .await
        .unwrap();
    fetch::fetch(Request::new("PUT", server.url("/p")))
        .await
        .unwrap()
        .text()
        .await
        .unwrap();
    fetch::fetch(
        Request::post(server.url("/p"))
            .header("content-type", "application/json")
            .header("User-Agent", "mine")
            .header("Accept-Encoding", "identity")
            .body(r#"{"a":1}"#),
    )
    .await
    .unwrap()
    .text()
    .await
    .unwrap();
    let reqs = server.requests();
    let base = [
        ("connection", "keep-alive"),
        ("accept", "*/*"),
        ("accept-language", "*"),
        ("sec-fetch-mode", "cors"),
    ];
    let with = |extra: &[(&'static str, &'static str)]| pairs(&[&base[..], extra].concat());
    // Expected sets come from Node 24's built-in fetch (see the module docs for `user-agent`).
    assert_eq!((reqs[0].method.as_str(), reqs[0].path.as_str()), ("GET", "/p?q=1"));
    assert_eq!(
        sorted_headers(&reqs[0]),
        with(&[("user-agent", "node"), ("accept-encoding", "gzip, deflate")])
    );
    assert_eq!(
        sorted_headers(&reqs[1]),
        with(&[
            ("x-custom", "A"),
            ("b-h", "1"),
            ("content-type", "text/plain;charset=UTF-8"),
            ("user-agent", "node"),
            ("accept-encoding", "gzip, deflate"),
            ("content-length", "5"),
        ])
    );
    assert_eq!(reqs[1].body, b"hello");
    assert_eq!(
        sorted_headers(&reqs[2]),
        with(&[
            ("user-agent", "node"),
            ("accept-encoding", "gzip, deflate"),
            ("content-length", "2")
        ])
    );
    assert_eq!(reqs[2].body, [1, 2]);
    assert_eq!(
        sorted_headers(&reqs[3]),
        with(&[
            ("user-agent", "node"),
            ("accept-encoding", "gzip, deflate"),
            ("content-length", "0")
        ])
    );
    assert_eq!(
        sorted_headers(&reqs[4]),
        with(&[
            ("content-type", "application/json"),
            ("user-agent", "mine"),
            ("accept-encoding", "identity"),
            ("content-length", "7")
        ])
    );
}

#[tokio::test]
async fn undici_rejects_or_strips_connection_level_headers() {
    let server = echo_server().await;
    let status = fetch::fetch(Request::get(server.url("/echo")).header("host", "evil"))
        .await
        .unwrap()
        .status();
    assert_eq!(status, 200);
    let res = fetch::fetch(Request::get(server.url("/echo")).header("connection", "close"))
        .await
        .unwrap();
    assert_eq!(res.status(), 200);
    res.text().await.unwrap();
    let reqs = server.requests();
    assert_eq!(reqs[0].header("host"), Some(server.addr.to_string().as_str()));
    assert_eq!(reqs[1].header("connection"), Some("close"));
    for (name, value, expected) in [
        (
            "transfer-encoding",
            "chunked",
            (
                "InvalidArgumentError",
                "invalid transfer-encoding header",
                "UND_ERR_INVALID_ARG",
            ),
        ),
        (
            "keep-alive",
            "timeout=5",
            (
                "InvalidArgumentError",
                "invalid keep-alive header",
                "UND_ERR_INVALID_ARG",
            ),
        ),
        (
            "upgrade",
            "websocket",
            ("InvalidArgumentError", "invalid upgrade header", "UND_ERR_INVALID_ARG"),
        ),
        (
            "expect",
            "100-continue",
            (
                "NotSupportedError",
                "expect header not supported",
                "UND_ERR_NOT_SUPPORTED",
            ),
        ),
    ] {
        let err = fetch::fetch(Request::get(server.url("/echo")).header(name, value))
            .await
            .unwrap_err();
        assert_eq!(
            fetch_failed(&err),
            (s(expected.0), s(expected.1), Some(s(expected.2))),
            "{name}"
        );
    }
}

#[tokio::test]
async fn redirects_follow_whatwg_rules() {
    let server = echo_server().await;
    for (path, method, expected_method, expected_ct, expected_body) in [
        ("/r301", "POST", "GET", None, ""),
        ("/r302", "POST", "GET", None, ""),
        ("/r303", "PUT", "GET", None, ""),
        ("/r307", "POST", "POST", Some("text/x"), "data"),
        ("/r301", "PUT", "PUT", Some("text/x"), "data"),
    ] {
        let res = fetch::fetch(
            Request::new(method, server.url(path))
                .header("content-type", "text/x")
                .header("authorization", "Bearer k")
                .body("data"),
        )
        .await
        .unwrap();
        assert_eq!(
            (res.status(), res.url(), res.redirected()),
            (200, server.url("/echo").as_str(), true),
            "{path} {method}"
        );
        let body = res.json().await.unwrap();
        assert_eq!(body["method"], expected_method, "{path} {method}");
        assert_eq!(body["content_type"].as_str(), expected_ct, "{path} {method}");
        assert_eq!(body["authorization"], "Bearer k", "{path} {method}");
        assert_eq!(body["body"], expected_body, "{path} {method}");
    }
    let head = fetch::fetch(Request::new("HEAD", server.url("/r303"))).await.unwrap();
    assert_eq!((head.status(), head.redirected(), head.has_body()), (200, true, false));

    let looped = fetch::fetch(Request::get(server.url("/loop"))).await.unwrap_err();
    assert_eq!(fetch_failed(&looped), (s("Error"), s("redirect count exceeded"), None));
    assert_eq!(server.requests().iter().filter(|r| r.path == "/loop").count(), 21);

    let noloc = fetch::fetch(Request::get(server.url("/noloc"))).await.unwrap();
    assert_eq!((noloc.status(), noloc.redirected()), (302, false));
    assert_eq!(noloc.text().await.unwrap(), "x");

    let badloc = fetch::fetch(Request::get(server.url("/badloc"))).await.unwrap_err();
    assert_eq!(fetch_failed(&badloc).1, "URL scheme must be a HTTP(S) scheme");

    let frag = fetch::fetch(Request::get(format!("{}#top", server.url("/frag"))))
        .await
        .unwrap();
    assert_eq!(frag.url(), server.url("/echo"));
}

