#[tokio::test]
async fn responses_expose_status_headers_and_decoded_bodies() {
    let server = echo_server().await;
    let res = fetch::fetch(Request::get(server.url("/headers"))).await.unwrap();
    assert_eq!((res.status(), res.status_text(), res.ok()), (200, "OK", true));
    let entries: Vec<(String, String)> = res
        .headers()
        .entries()
        .into_iter()
        .filter(|(k, _)| k != "connection" && k != "content-length")
        .collect();
    assert_eq!(
        entries,
        vec![
            (s("content-type"), s("application/json")),
            (s("set-cookie"), s("a=1")),
            (s("set-cookie"), s("b=2")),
            (s("x-dup"), s("1, 2")),
            (s("x-latin"), s("caf\u{c3}\u{a9}")),
        ]
    );

    let gzip = fetch::fetch(Request::get(server.url("/gzip"))).await.unwrap();
    assert_eq!(gzip.text().await.unwrap(), "hello gzip");
    let br = fetch::fetch(Request::get(server.url("/br"))).await.unwrap();
    assert_eq!(br.text().await.unwrap(), "hello br");

    let bom = fetch::fetch(Request::get(server.url("/bom"))).await.unwrap();
    assert_eq!(bom.text().await.unwrap(), "hi \u{fffd}!");

    let json = fetch::fetch(Request::get(server.url("/json"))).await.unwrap();
    let value = json.json().await.unwrap();
    assert_eq!(value, serde_json::json!({"b": 1, "a": [true, null]}));
    assert_eq!(value.as_object().unwrap().keys().collect::<Vec<_>>(), ["b", "a"]);

    let bad = fetch::fetch(Request::get(server.url("/badjson"))).await.unwrap();
    assert_eq!(
        shape(&bad.json().await.unwrap_err()),
        (s("SyntaxError"), s("Unexpected end of JSON input"), None)
    );

    let no_content = fetch::fetch(Request::get(server.url("/204"))).await.unwrap();
    assert_eq!((no_content.status(), no_content.has_body()), (204, false));
    assert_eq!(no_content.text().await.unwrap(), "");

    let head = fetch::fetch(Request::new("HEAD", server.url("/json"))).await.unwrap();
    assert!(!head.has_body());
}

