#[tokio::test]
async fn connection_refused_matches_node() {
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    drop(listener);
    let err = fetch::fetch(Request::get(format!("http://127.0.0.1:{port}/")))
        .await
        .unwrap_err();
    fetch_failed(&err);
    match cause(&err) {
        Error::Node(NodeError {
            code,
            errno,
            syscall,
            message,
            ..
        }) => {
            assert_eq!(code, "ECONNREFUSED");
            assert_eq!(syscall, "connect");
            assert_eq!(message, &format!("connect ECONNREFUSED 127.0.0.1:{port}"));
            #[cfg(unix)]
            assert_eq!(*errno, -libc_econnrefused());
            #[cfg(not(unix))]
            let _ = errno;
        }
        other => panic!("expected a Node error, got {other:?}"),
    }
}

#[cfg(unix)]
fn libc_econnrefused() -> i32 {
    std::io::Error::from(std::io::ErrorKind::ConnectionRefused)
        .raw_os_error()
        .unwrap_or(if cfg!(target_os = "linux") { 111 } else { 61 })
}

#[tokio::test]
async fn abort_rejects_with_the_signal_reason() {
    let server = echo_server().await;
    let pre = AbortController::new();
    pre.abort(None);
    let err = fetch::fetch(Request::get(server.url("/echo")).signal(pre.signal()))
        .await
        .unwrap_err();
    assert_eq!(shape(&err).0, "AbortError");
    assert_eq!(shape(&err).1, "This operation was aborted");
    assert!(err.is_abort());

    let custom = AbortController::new();
    custom.abort(Some(AbortReason::error("Error", "stop now")));
    let err = fetch::fetch(Request::get(server.url("/echo")).signal(custom.signal()))
        .await
        .unwrap_err();
    assert_eq!((shape(&err).0, shape(&err).1), (s("Error"), s("stop now")));

    let during = AbortController::new();
    let signal = during.signal();
    let pending = tokio::spawn(fetch::fetch(Request::get(server.url("/slow-headers")).signal(signal)));
    tokio::time::sleep(Duration::from_millis(50)).await;
    during.abort(None);
    let err = pending.await.unwrap().unwrap_err();
    assert_eq!(shape(&err).1, "This operation was aborted");

    let timeout = fetch::fetch(Request::get(server.url("/slow-headers")).signal(AbortSignal::timeout(50)))
        .await
        .unwrap_err();
    assert_eq!(
        (shape(&timeout).0, shape(&timeout).1),
        (s("TimeoutError"), s("The operation was aborted due to timeout"))
    );

    let mid = AbortController::new();
    let res = fetch::fetch(Request::get(server.url("/slow-body")).signal(mid.signal()))
        .await
        .unwrap();
    let mut stream = res.body_stream().unwrap();
    assert_eq!(stream.next().await.unwrap().unwrap(), Bytes::from("first"));
    mid.abort(None);
    let err = stream.next().await.unwrap().unwrap_err();
    assert_eq!(
        (shape(&err).0, shape(&err).1),
        (s("AbortError"), s("This operation was aborted"))
    );
    assert!(stream.next().await.is_none());
}

#[tokio::test]
async fn streams_sse_over_the_network() {
    let server = echo_server().await;
    let res = fetch::fetch(Request::get(server.url("/sse"))).await.unwrap();
    assert_eq!(res.headers().get("content-type").as_deref(), Some("text/event-stream"));
    let events: Vec<SseEvent> = res.sse().unwrap().map(|e| e.unwrap()).collect().await;
    assert_eq!(
        events,
        vec![
            SseEvent {
                event: s("start"),
                data: s("{\"n\":1}"),
                id: None,
                retry: None
            },
            SseEvent {
                event: s("message"),
                data: s("café\ntwo"),
                id: None,
                retry: None
            },
            SseEvent {
                event: s("message"),
                data: s("end"),
                id: Some(s("3")),
                retry: Some(50)
            },
        ]
    );
}

#[tokio::test]
async fn data_urls_match_undici() {
    for (url, expected) in DATA_URLS {
        let got = match fetch::fetch(Request::get(*url)).await {
            Ok(res) => {
                let meta = (
                    res.status(),
                    s(res.status_text()),
                    res.headers().get("content-type").unwrap_or_default(),
                    s(res.url()),
                );
                Ok((meta, res.bytes().await.unwrap().to_vec()))
            }
            Err(e) => Err(fetch_failed(&e).1),
        };
        let want = match expected {
            Ok((status_text, content_type, body, res_url)) => {
                Ok(((200, s(status_text), s(content_type), s(res_url)), body.to_vec()))
            }
            Err(message) => Err(s(message)),
        };
        assert_eq!(got, want, "{url}");
    }
}

#[test]
fn request_and_body_helpers() {
    let req = Request::post("http://x/").body(vec![0xFFu8, b'a']);
    assert_eq!(req.body_text().as_deref(), Some("\u{fffd}a"));
    assert_eq!(req.body_json(), None);
    assert_eq!(Request::default().method, "GET");
    let body: Body = "abc".into();
    assert_eq!((body.len(), body.as_bytes()), (3, &b"abc"[..]));
    assert_eq!(
        Body::from(Bytes::from_static(b"x")),
        Body::Bytes(Bytes::from_static(b"x"))
    );
    let dbg = format!("{:?}", Request::get("http://x/").header("a", "1"));
    assert!(dbg.contains("\"a\": \"1\""), "{dbg}");
}

#[test]
fn default_client_is_shared_and_replaceable() {
    let a = fetch::default_client();
    let b = fetch::default_client();
    // reqwest clients are handles; formatting both shows the same configuration.
    assert_eq!(format!("{a:?}"), format!("{b:?}"));
    assert!(format!("{a:?}").contains("node"), "{a:?}");
}

#[tokio::test]
async fn idle_timeouts_map_to_undici_errors() {
    let server = echo_server().await;
    let client = fetch::client_builder()
        .read_timeout(Duration::from_millis(200))
        .build()
        .unwrap();
    let err = fetch::fetch_with_client(&client, Request::get(server.url("/slow-headers")))
        .await
        .unwrap_err();
    assert_eq!(
        fetch_failed(&err),
        (
            s("HeadersTimeoutError"),
            s("Headers Timeout Error"),
            Some(s("UND_ERR_HEADERS_TIMEOUT"))
        )
    );
    let res = fetch::fetch_with_client(&client, Request::get(server.url("/slow-body")))
        .await
        .unwrap();
    let err = res.text().await.unwrap_err();
    assert_eq!(shape(&err), (s("TypeError"), s("terminated"), None));
    assert_eq!(
        shape(cause(&err)),
        (
            s("BodyTimeoutError"),
            s("Body Timeout Error"),
            Some(s("UND_ERR_BODY_TIMEOUT"))
        )
    );
}

#[tokio::test]
async fn custom_clients_set_the_user_agent() {
    // http-dispatcher.ts installs npm undici, whose fetch sends `user-agent: undici`.
    let server = echo_server().await;
    let client = fetch::client_builder().user_agent("undici").build().unwrap();
    fetch::fetch_with_client(&client, Request::get(server.url("/echo")))
        .await
        .unwrap()
        .text()
        .await
        .unwrap();
    fetch::fetch_with_client(&client, Request::get(server.url("/echo")).header("user-agent", "mine"))
        .await
        .unwrap()
        .text()
        .await
        .unwrap();
    let reqs = server.requests();
    assert_eq!(reqs[0].header("user-agent"), Some("undici"));
    assert_eq!(reqs[1].header("user-agent"), Some("mine"));
}

#[tokio::test]
async fn dns_failures_are_getaddrinfo_errors() {
    let err = fetch::fetch(Request::get("http://nonexistent.invalid/"))
        .await
        .unwrap_err();
    match cause(&err) {
        Error::Node(NodeError {
            code, syscall, message, ..
        }) => {
            assert_eq!(syscall, "getaddrinfo");
            assert!(code == "ENOTFOUND" || code == "EAI_AGAIN", "{code}");
            assert_eq!(message, &format!("getaddrinfo {code} nonexistent.invalid"));
        }
        other => panic!("expected a getaddrinfo error, got {other:?}"),
    }
}
